import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"离为火","description":"周易折中 - 离为火","frontmatter":{"title":"离为火","description":"周易折中 - 离为火"},"headers":[],"relativePath":"zh/classics/zhezhong/036.md","filePath":"zh/classics/zhezhong/036.md"}'),h={name:"zh/classics/zhezhong/036.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="离为火" tabindex="-1">离为火 <a class="header-anchor" href="#离为火" aria-label="Permalink to “离为火”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>离序卦：坎者，陷也。陷必有所丽，故受之以离。离者，丽也。陷于险难之中，则必有所附丽，理自然也。离所以次坎也。离，丽也，明也。取其阴丽于上下之阳，则为附丽之义；取其中虚，则为明义。离为火，火体虚丽于物而明者也；又为日，亦以虚明之象。</p><p>离：利贞，亨；畜牝牛，吉。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>离，丽也。阴丽于阳，其象为火，体阴而用阳也。物之所丽，贵乎得正。牝牛柔顺之物也，故占者能正则亨，而畜牝牛则吉也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>离，丽也。万物莫不皆有所丽，有形则有丽矣。在人则为所亲附之人，所由之道，所主之事，皆其所丽也。人之所丽，利于贞正。得其正，则可以亨通。故曰“离利贞亨”。畜牝牛吉，牛之性顺而又牝焉，顺之至也。既附丽于正，必能顺于正道。如牝牛则吉也。畜牝牛，谓养其顺德。人之顺德，由养以成。既丽于正，当养习以成其顺德也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：离之为卦，以柔为正，故必贞而后乃亨。柔处于内而履正中，牝之善也。外强而内顺，牛之善也。离之为体，以柔顺为主者也，故不可以畜刚猛之物，而吉于畜牝牛也。</p></li><li><p>郭氏忠孝曰 ：干为马，坤为牝马。坤为牛，离为牝牛，象之宜也。</p></li><li><p>朱子语类 ：问：离卦是阳包阴，占利畜牝牛，便也是宜畜柔顺之物。曰：然。</p></li><li><p>呉氏澄曰 ：牛、牝皆坤象，离中画一阴，坤之中画也，故象牝牛。</p></li><li><p>胡氏炳文曰 ：坎之明在内，以刚健而行之于外；离之明在外，当柔顺以养之于中。</p></li><li><p>呉氏曰慎曰 ：坎性就下，下不已则入坎窞；离性炎上，炎之盛则突如焚如。坎陷欲之类也，离炎忿之类也。坎维心亨以刚中，则不陷；离畜牝牛，以中顺则不突。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>畜牝牛，胡氏、呉氏之说为切。盖离明也，高明柔克，则用明而不伤。</p><p>象曰：明两作，离大人以继明照于四方</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>作起也</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>若云两明，则是二明，不见继明之义。故云明两，明而重两，谓相继也。作离，明两而为离，继明之义也。震巽之类，亦取洊随之义，然离之义尤重也。大人以徳言，则圣人以位言，则王者。大人观离明相继之象，以世继其明徳，照临于四方。大凡以明相继，皆继明也。举其大者，故以世袭继照言之。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：继，谓不绝也。明照相继，不绝旷也。</p></li><li><p>孔氏颖逹曰：继续其明，乃照于四方。若明不继续，则不得久为照临。</p></li><li><p>朱子语类云：明两作，犹言水洊至今日明，来日又明。明字便是指日而言，只是一个明两番作。</p></li><li><p>徐氏在汉曰：继明者，无时不明也。照于四方者，无处不照也。惟其无时不明，所以无处不照，是之谓明明德于天下也。</p></li></ul><p>《彖》曰：离，丽也；日月丽乎天，百谷草木丽乎土；重明以丽乎正，乃化成天下</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>离丽也，谓附丽也。如日月则丽于天，百谷草木则丽于土。万物莫不各有所丽，天地之中无无丽之物。在人当审其所丽，丽丽得其正则能亨也。重明以丽乎正，以卦才言也。上下皆离，重明也。五二皆处中正，丽乎正也。君臣上下皆有明德而处中正，可以化天下成文明之俗也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰：日月丽乎天而成明，百谷草木丽乎土而成文，故离为文又为明。</p></li><li><p>齐氏梦龙曰：龟山杨氏云，火无常形，丽物而有形，最得本旨。人之生也，得水为精，得火为神。其合也，气聚而形成于有其分也；气散而神泯于无。盖精所以为形，而神丽于形者也。天地形之大者也，日月丽天，百谷草木丽土，其神之发见而可见者也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>项氏、齐氏说则是阳丽乎阴而以为阴丽乎阳者非矣。惟张子正蒙之说得之。</p><p>柔丽乎中正，故亨；是以畜牝牛吉也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦辞。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>二五以柔顺丽于中正，所以能亨。人能养其至顺以丽中正，则吉。故曰畜牝牛吉也。或曰：“二则中正矣，五以阴居阳得为正乎？”曰：“离主于所丽，五中正之位，六丽于正位，乃为正也。”学者知时义而不失轻重，则可以言易矣。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰：“重明以丽乎正”此统论一卦之义以释卦名也，“柔丽乎中正”此以二五成卦之爻释卦辞也。</p></li><li><p>胡氏炳文曰：坎之刚中，九五分数多，故九五曰“坎不盈”，卦辞释有孚亦曰“水流而不盈”。离之中正，六二分数多，故卦辞曰“畜牝牛吉”，而六二爻辞亦曰“黄离元吉”。</p></li></ul><p>初九：履错然，敬之无咎</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>以刚居下而处明体，志欲上进，故有履错然之象。敬之则无咎矣，戒占者宜如是也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>阳固好动，又居下而离体。阳居下则欲进，离性炎上，志在上丽，几于躁动。其履错然，谓交错也。虽未进而迹已动矣，动则失居下之分而有咎也。然其刚明之才，若知其义而敬慎之，则不至于咎矣。初在下无位者也，明其身之进退乃所丽之道也。其志既动，不能敬慎，则妄动，是不明所丽，乃有咎也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：身处离初，故其所履践恒错然。敬慎不敢自宁，故云“履错然敬之无咎”。若能如此恭敬，则得避其祸而无咎。</p></li><li><p>王氏昭素曰 ：处万物相见之初，履错杂之时。</p></li><li><p>胡氏瑗曰 ：错然者，敬之之貌也。居离之初，如日之初生，于事之初，则当常错然警惧以进德修业，所以得免其咎。</p></li><li><p>冯氏当可曰 ：日方出人夙兴之晨也，履错然动之始也。于其始而加敬，则终必吉。祸福几微，每萌于初动之时，故戒其初。</p></li><li><p>赵氏彦肃曰 ：能敬则动与物交皆天理也，不能敬则役于物而生咎矣。日出而作，故发此象。</p></li><li><p>胡氏一桂曰 ：错然是事物纷错之意，能敬则心有主宰，酬应不乱，可免于咎；不能敬则反是。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>履错然，王氏、冯氏、胡氏之说为是。盖错杂者，处应物之初也；敬者，养明德之本也。人心之德，敬则明，不敬则昏。于应物之初而知敬，其即于咎者鲜矣。</p><p>象曰：履错之敬以辟咎也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>履错然欲动而知敬愼，不敢进，所以求辟免过咎也。居明而刚，故知而能辟，不刚明则妄动矣。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><p>徐氏在汉曰：敬以直内，坤之徳也。履错之敬，是体坤之徳，所谓畜牝牛吉者也。咎不期远而自远，故曰以辟咎也。</p><p>六二：黄离，元吉</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>黄中色柔，离乎中而得其正，故其象占如此。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二居中得正，丽于中正也。黄中之色，文之美也。文明中正，美之盛也。故云“黄离”，以文明中正之德，上同于文明中顺之君，其明如是，所丽如是，大善之吉也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：居中得位，以柔处柔，履文明之盛而得其中，故曰“黄离元吉”也。</p></li><li><p>刘氏牧曰 ：离为火之象，焰猛而易烬（如九四所示）。过盛则有衰竭之凶（如九三所示）。惟二得中，离之元吉也。</p></li><li><p>郭氏雍曰 ：离之六爻，二五为美。五得中而非正，柔丽中正者，惟六二尽之。黄为中之色，而德之至美者也。故言元吉，其义与坤六五相类。</p></li><li><p>俞氏琰曰 ：九三言“日昃之离”，六二其“日中之离”乎？居下卦之中而得其中道，故比他爻为最吉。六二盖离之主爻也。</p></li><li><p>杨氏启新曰 ：畜牝牛而利贞，六二得之，明而不失其中正，故曰“黄离”。</p></li></ul><p>象曰：黄离元吉，得中道也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>所以元吉者，以其得中道也。不云正者，离以中为重，所以成文明由中也。正在其中矣。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><p>郭氏忠孝曰：离之所以亨，柔丽乎中正，故亨也。黄离之所以元吉，文明而用中，故元吉也。故尽一卦之美，其惟六二乎。</p><p>九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶。</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>重离之间，前明将尽，故有日昃之象。不安常以自乐，则不能自处而凶矣。戒占者宜如是也。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>八纯卦皆有二体之义。离卦，内外皆明。九三居下体之终，是前明将尽，后明当继之时。人之始终，时之革易也，故为日昃之离。日下昃之明也，昃则将没矣。以理言之，盛必有衰，始必有终，常道也。达者顺理为乐，缶常用之器也，鼓缶而歌，乐其常也。不能如是，则以大耋为嗟，忧乃为凶也。大耋，倾没也，人之终尽。达者则知其常理，乐天而已，遇常皆乐，如鼓缶而歌。不达者则恐怛有将尽之悲，乃大耋之嗟，为其凶也。此处死生之道也。耋与昳同。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苟氏爽曰：初为日出，二为日中，三为日昃。</p></li><li><p>梁氏寅曰：三居下离之终，乃日昃之时也。夫持满定倾，非中正之君子不能。三处日之夕，而过刚不中，其志荒矣。故不鼓缶而歌，则大耋之嗟。其歌也，乐之失常也；其嗟也，哀之失常也。哀乐失常，能无凶乎？君子值此之时，则思患之心与乐天之诚并行而不悖，是固不暇于歌矣，而亦何至于嗟乎？</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>梁氏之说独得爻义。盖日昃者，喻心之昏，非喻境之变也。</p><p>象曰：日昃之离，何可久也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>日既倾昃，明能久乎？明者知其然也，故求人以继其事，退处以休其身。安常处顺，何足以为凶也。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>日昃喻心德之昏也。心德明则常继，昏则不能以久。</p><p>九四：突如其来，如焚如死，如弃如。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>后明将继之时，而九四以刚迫之，故其象如此。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>九四离下体而升上体，继明之初，故言继承之义。在上而近君，继承之地也。以阳居离体而处四，刚躁而不中正，且重刚以不正而刚盛之，突如而来，非善继者也。夫善继者，必有巽让之诚、顺承之道，若舜启然。今四突如其来，失善继之道也。又承六五阴柔之君，其刚盛陵烁之气焰如焚然，故曰焚如。四之所行不善如此，必被祸害，故曰死如。失继绍之义，承上之道皆逆德也，众所弃绝，故云弃如。至于死弃，祸之极矣，故不假言凶也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>章氏潢曰：明之于人，犹火之于木。火宿于木而能焚木，明本于人而能害人。顾用之何如耳。九四不中不正，刚气燥暴，其害若此。</p></li><li><p>何氏楷曰：三处下卦之尽，似日之过中；四处上卦之始，似火之骤烈。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>离，明德也。继明者，所谓有缉熙于光明，其明不息也。与继世之义全无交涉。因先儒有以明两为继世者，故程传用说九四爻义于经意似远。章氏、何氏谓燥暴骤烈者得之，不能以顺德养其明，过也。</p><p>象曰：突如其来，如无所容也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>无所容，言焚死弃也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>上陵其君，不顺所承，人恶众弃，天下所不容也。案突如其来，如书所谓昏暴者是也，非人不容之，自若无所容尔。</p><p>六五：出涕沱若，戚嗟若，吉。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以阴居尊，柔丽乎中，然不得其正而迫于上下之阳，故忧惧如此，然后得吉。戒占者宜如是也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>六五居尊位而守中，有文明之德，可谓善矣。然以柔居上，在下无助，独附丽于刚强之间，危惧之也。唯其明也，故能畏惧之深，至于出涕；忧虑之深，至于戚嗟，所以能保其吉也。出涕戚嗟，极言其忧惧之深耳，时当然也。居尊位而文明，知忧畏如此，故得吉。若自恃其文明之德与所丽中正，泰然不惧，则安能保其吉也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>蔡氏渊曰：坎离之用在中，二五皆卦之中也。坎五当位而二不当位，故五为胜；离二当位而五不当位，故二为胜。</p></li><li><p>刘氏定之曰：坎者，阴险之卦，惟刚足以济之，沈潜刚克也；离者，阳躁之卦，惟柔足以和之，高明柔克也。二五同归于吉，以柔而然也。</p></li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>惟六二为得明德之正，三之歌嗟，四之突来，则明德昏而性情荡，忿欲仍而灾患至矣。能返之者，其惟哀悔之心乎？五有中德，又适昏极将明之候，故取象如此。三之嗟乐过而悲也，五之嗟自怨自艾也。</p><p>象曰：六五之吉，离王公也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>六五之吉者，所丽得王公之正位也。据在上之势而明察事理，畏惧忧虞以持之，所以能吉也。不然，岂能安乎？</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><p>赵氏彦肃曰：明极故忧深，忧深故祸弭。又丽于尊位，故致吉也。 蔡氏清曰：味“离王公也”之词，则知诸卦之五所谓尊位者，不必皆谓天王。凡诸侯之各君其国者，亦足当五也。</p><p>上九：王用出征，有嘉折首，获匪其丑，无咎。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>刚明及远，威震而刑不滥，无咎之道也，故其象占如此。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>九以阳居上，在离之终，刚明之极者也。明则能照，刚则能断。能照足以察邪恶，能断足以行威刑。故王者宜用如是刚明以辨天下之邪恶而行其征伐，则有嘉美之功也。征伐用刑之大者，夫明极则无微不照，断极则无所寛宥。不约之以中，则伤于严察矣。去天下之恶若尽，究其渐染诖误，则何可胜诛？所伤残亦甚矣。故但当拆取其魁首，所执获者非其丑类，则无残暴之咎也。《书》曰：“歼厥渠魁，胁从罔治。”</p><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>上九承四五之后，有重明之象。故在人心，则为克己而尽其根株；在国家，则为除乱而去其元恶。《诗》云：“如火烈烈，则莫我敢遏。苞有三蘖，莫遂莫达。”此爻之义也。</p><p>象曰：王用出征，以正邦也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>王者用此上九之徳，明照而刚断，以察除天下之恶，所以正治其邦国。刚明居上之道也。</p>',113)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
